Boolean dst_log_read(Dst_Log * log)
{
  if(dst_vars.log_count) // read if at least one log is done
    {
      memcpy(log , dst_vars.log, sizeof(Dst_Log) * DST_LOG_SIZE) ;
      #if DBG_DST == 1 
        dst_dbg_print("\r\nDst Log Read", NULL, NULL) ;
      #endif
      return TRUE ;
    }
  return FALSE ;
}
